export const runtime="nodejs";const operationSchema=z.string().uuid();
function safeFileName(request:Request){const encoded=request.headers.get("x-file-name");if(!encoded||encoded.length>600)return null;try{const decoded=decodeURIComponent(encoded);const name=decoded.split(/[\\/]/u).pop()?.trim()??"";if(!name||name.length>180||/[\u0000\r\n]/u.test(name))return null;return name;}catch{return null;}}
